import { Dispatch, SetStateAction, useMemo, useRef } from 'react';

import { _useControllableState } from '../../core/hooks/useControllableState.js';
import {
  DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID,
  DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
  DATA_TABLE_SUB_ROW_TRIGGER_ID,
} from '../DataTable/constants.js';
import { TableColumn } from '../types/shared-table-types.js';
import { validateColumnOrder } from '../utils/column-order-utils.js';
import { insertColumnId } from '../utils/column-utils.js';

interface ConfigType {
  /**
   * Default column order state (uncontrolled).
   */
  defaultColumnOrder: string[] | undefined;
  /**
   * Column order state (controlled).
   */
  columnOrder: string[] | undefined;
  /**
   * Columns configured via column definition
   */
  originalColumns: TableColumn[];
  /**
   * Called when the column order changes.
   */
  onColumnOrderChangeProp: ((columnOrder: string[]) => void) | undefined;
  /**
   * Notifies that the selectableRows are enabled and that we have an extra column in the table.
   */
  selectableRowsEnabled: boolean;
  /**
   * Notifies that the expandable rows are enabled and that we have an extra column in the table.
   */
  expandableRowsEnabled: boolean;
  /**
   * Notifies that the sub rows are enabled and that we have an extra column in the table.
   */
  subRowsEnabled: boolean;
}

/**
 * Checks if the order of items in the given columnOrder array is valid. The order in config.originalColumns is
 * taken as being the correct order. If columnOrder is invalid, this function returns an empty array.
 * Furthermore, if the array is valid and if prefix columns are enabled in the table, this function
 * adds their IDs to the beginning of the returned array.
 *
 * @param config - ConfigType
 *
 * @returns updated column order array and corresponding setter function.
 */
export function usePrepareColumnOrder(config: ConfigType): {
  columnOrder: string[];
  setColumnOrder: Dispatch<SetStateAction<string[]>>;
} {
  const {
    defaultColumnOrder,
    columnOrder: columnOrderProp,
    originalColumns,
    onColumnOrderChangeProp,
    selectableRowsEnabled,
    expandableRowsEnabled,
    subRowsEnabled,
  } = config;

  const prevColumnOrder = useRef<string[] | undefined>(columnOrderProp);

  const [columnOrder, setColumnOrder] = _useControllableState({
    defaultValue: defaultColumnOrder,
    value: columnOrderProp,
    onChange: onColumnOrderChangeProp,
  });

  const isColumnOrderValid = useMemo(() => {
    return validateColumnOrder(columnOrder, originalColumns);
  }, [columnOrder, originalColumns]);

  // array undefined and array of length 0 is invalid per validateColumnOrder, so no need for extra check
  if (!isColumnOrderValid) {
    return {
      columnOrder: prevColumnOrder.current ?? [],
      setColumnOrder,
    };
  }

  // when prefix columns are enabled we include them at the beginning of the columnOrder array.
  selectableRowsEnabled &&
    insertColumnId(columnOrder, DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID);

  expandableRowsEnabled &&
    insertColumnId(columnOrder, DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID, [
      DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
    ]);

  subRowsEnabled &&
    insertColumnId(columnOrder, DATA_TABLE_SUB_ROW_TRIGGER_ID, [
      DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
      DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID,
    ]);
  prevColumnOrder.current = columnOrder;
  return { columnOrder, setColumnOrder };
}
